CREATE SCHEMA IF NOT EXISTS puentes;
SET search_path TO puentes;
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('DOM','Inspector','Mantención')));
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON users TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS bridges(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, location TEXT NOT NULL, criticality TEXT NOT NULL CHECK(criticality IN ('Baja','Media','Alta')), simulated BIGINT NOT NULL DEFAULT 0);
ALTER TABLE bridges ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON bridges TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS components(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bridge_id BIGINT NOT NULL REFERENCES bridges(id), name TEXT NOT NULL, UNIQUE(bridge_id,name));
ALTER TABLE components ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON components TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS sensors(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, component_id BIGINT NOT NULL REFERENCES components(id), code TEXT UNIQUE NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('vibracion','inclinacion')), unit TEXT NOT NULL, location TEXT NOT NULL DEFAULT 'Pendiente de precisar', reference_value DOUBLE PRECISION, previous_unit TEXT);
ALTER TABLE sensors ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON sensors TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS measurements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sensor_id BIGINT NOT NULL REFERENCES sensors(id), value DOUBLE PRECISION, unit TEXT NOT NULL, measured_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('valido','invalido','no_disponible')), simulated BIGINT NOT NULL, external_id TEXT UNIQUE, author_id BIGINT REFERENCES users(id), created_at TEXT NOT NULL, evaluation TEXT NOT NULL DEFAULT 'Histórico: evaluación no registrada', reference_value DOUBLE PRECISION, variation DOUBLE PRECISION, specification TEXT NOT NULL DEFAULT 'historica');
ALTER TABLE measurements ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON measurements TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS "inspections"(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bridge_id BIGINT NOT NULL REFERENCES bridges(id), component_id BIGINT NOT NULL REFERENCES components(id), inspected_at TEXT NOT NULL, inspector_id BIGINT NOT NULL REFERENCES users(id), condition TEXT NOT NULL CHECK(condition IN ('Buena','Regular','Mala','Crítica','Baja','Media','Alta')), description TEXT NOT NULL, simulated BIGINT NOT NULL DEFAULT 0, standard TEXT NOT NULL DEFAULT 'historica');
ALTER TABLE inspections ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON inspections TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS photos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, inspection_id BIGINT NOT NULL REFERENCES inspections(id), filename TEXT UNIQUE NOT NULL);
ALTER TABLE photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON photos TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS rules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bridge_id BIGINT NOT NULL REFERENCES bridges(id), kind TEXT NOT NULL CHECK(kind IN ('vibracion','inclinacion','visual')), threshold DOUBLE PRECISION, condition TEXT, label TEXT NOT NULL, simulated BIGINT NOT NULL, active BIGINT NOT NULL DEFAULT 1, author_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, comparison TEXT NOT NULL DEFAULT 'gt', standard TEXT NOT NULL DEFAULT 'historica', severity TEXT NOT NULL DEFAULT 'Sin nivel', unit TEXT);
ALTER TABLE rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON rules TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS alerts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bridge_id BIGINT NOT NULL REFERENCES bridges(id), rule_id BIGINT NOT NULL REFERENCES rules(id), measurement_id BIGINT REFERENCES measurements(id), inspection_id BIGINT REFERENCES inspections(id), created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Activa' CHECK(status IN ('Activa','En atención','Resuelta')), simulated BIGINT NOT NULL, severity TEXT NOT NULL DEFAULT 'Sin nivel', standard TEXT NOT NULL DEFAULT 'historica', UNIQUE(rule_id,measurement_id), UNIQUE(rule_id,inspection_id));
ALTER TABLE alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON alerts TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS alert_notes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, alert_id BIGINT NOT NULL REFERENCES alerts(id), author_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, note TEXT NOT NULL, inspection_id BIGINT REFERENCES inspections(id));
ALTER TABLE alert_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON alert_notes TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS tasks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bridge_id BIGINT NOT NULL REFERENCES bridges(id), component_id BIGINT REFERENCES components(id), alert_id BIGINT REFERENCES alerts(id), description TEXT NOT NULL, assignee_id BIGINT NOT NULL REFERENCES users(id), planned_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pendiente' CHECK(status IN ('Pendiente','En ejecución','Completada')), author_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
ALTER TABLE tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON tasks TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id BIGINT, details TEXT NOT NULL, created_at TEXT NOT NULL);
ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON audit TO puentes_app USING (true) WITH CHECK (true);
CREATE TABLE IF NOT EXISTS inspection_plans(
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bridge_id BIGINT NOT NULL REFERENCES bridges(id),
        component_id BIGINT NOT NULL REFERENCES components(id), inspector_id BIGINT NOT NULL REFERENCES users(id),
        planned_date TEXT NOT NULL, description TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'Programada' CHECK(status IN ('Programada','Realizada','Cancelada')),
        inspection_id BIGINT UNIQUE REFERENCES inspections(id), author_id BIGINT NOT NULL REFERENCES users(id),
        created_at TEXT NOT NULL);
ALTER TABLE inspection_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON inspection_plans TO puentes_app USING (true) WITH CHECK (true);
CREATE INDEX IF NOT EXISTS measurement_history ON measurements(sensor_id,measured_at DESC);
CREATE INDEX IF NOT EXISTS alerts_bridge ON alerts(bridge_id,status);
CREATE INDEX IF NOT EXISTS components_bridge ON components(bridge_id);
CREATE INDEX IF NOT EXISTS sensors_component ON sensors(component_id);
CREATE INDEX IF NOT EXISTS inspection_bridge ON inspections(bridge_id,inspected_at DESC);
REVOKE ALL ON SCHEMA puentes FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA puentes FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA puentes TO puentes_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA puentes TO puentes_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA puentes TO puentes_app;
